// PanelWorks posts: {form, object, event, args, values, time}
// Reply with {set: {"Obj.Prop": value}, call: [[obj, method, ...args]], msgbox}
const b = $input.first().json.body || {};
const t = $now.toFormat('HH:mm:ss');
const v = b.values || {};
let out;

if (b.event === 'Poll') {
  out = { set: { 'lblServer.Caption': 'n8n clock: ' + t } };
} else if (b.object === 'cmdAsk' && b.event === 'Click') {
  const name = (v['txtName.Text'] || '').trim() || 'stranger';
  out = {
    set: {
      'lblReply.Caption': 'Hello ' + name + ', from n8n at ' + t,
      'shpLamp.FillColor': 'dodger blue'
    },
    call: [['lstLog', 'AddItem', t + '  n8n handled cmdAsk_Click for ' + name, 0]]
  };
} else if (b.object === 'chkAlert' && b.event === 'Click') {
  const on = Number(v['chkAlert.Value']) === 1;
  out = {
    set: { 'shpLamp.FillColor': on ? 'red' : 'gray' },
    call: [['lstLog', 'AddItem', t + '  alert ' + (on ? 'armed' : 'cleared') + ' by n8n', 0]]
  };
} else {
  out = { call: [['lstLog', 'AddItem', t + '  n8n saw ' + b.object + '_' + b.event, 0]] };
}
return [{ json: out }];
